class StairView:Control {public D Model;public double Yaw=-35,Pitch=30,Zoom=1;bool drag;Point anchor;public StairView(){DoubleBuffered=true;BackColor=Color.FromArgb(242,244,237);MouseDown+=(s,e)=>{drag=true;anchor=e.Location;Capture=true;};MouseUp+=(s,e)=>{drag=false;Capture=false;};MouseMove+=(s,e)=>{if(drag){Yaw+=(e.X-anchor.X)*.6;Pitch=Math.Max(2,Math.Min(88,Pitch-(e.Y-anchor.Y)*.4));anchor=e.Location;Invalidate();}};MouseWheel+=(s,e)=>{Zoom=Math.Max(.3,Math.Min(4,Zoom*(e.Delta>0?1.12:.89)));Invalidate();};MouseEnter+=(s,e)=>Focus();}
struct P {public double X,Y,Z;public P(double x,double y,double z){X=x;Y=y;Z=z;}}
