protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(Model==null){g.DrawString("ġ���� �Է��ϸ� 3D ������ ����մϴ�.",Font,Brushes.DarkGreen,20,20);return;}var boxes=J.Rows(Model,"boxes");if(boxes.Count==0)return;double a=Yaw*Math.PI/180,p=Pitch*Math.PI/180;Func<P,double[]> project=v=>new[]{v.X*Math.Cos(a)-v.Y*Math.Sin(a),(v.X*Math.Sin(a)+v.Y*Math.Cos(a))*Math.Sin(p)-v.Z*Math.Cos(p),(v.X*Math.Sin(a)+v.Y*Math.Cos(a))*Math.Cos(p)+v.Z*Math.Sin(p)};var faces=new List<Face>();var all=new List<double[]>();var labels=new List<Tuple<P,string>>();foreach(D b in boxes){double x=(double)J.Num(b,"x"),y=(double)J.Num(b,"y"),z=(double)J.Num(b,"z"),w=(double)J.Num(b,"width"),d=(double)J.Num(b,"depth"),t=(double)J.Num(b,"thickness");P[] v={new P(x,y,z),new P(x+w,y,z),new P(x+w,y+d,z),new P(x,y+d,z),new P(x,y,z+t),new P(x+w,y,z+t),new P(x+w,y+d,z+t),new P(x,y+d,z+t)};int[][] indexes={new[]{0,1,2,3},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}};Color[] colors={Color.FromArgb(111,76,43),Color.FromArgb(201,161,107),Color.FromArgb(161,112,67),Color.FromArgb(140,94,55),Color.FromArgb(150,104,62),Color.FromArgb(174,126,76)};for(int i=0;i<6;i++){P[] pts=indexes[i].Select(k=>v[k]).ToArray();faces.Add(new Face{Points=pts,Depth=pts.Average(pt=>project(pt)[2]),Color=J.Text(b,"kind")=="landing"?Color.FromArgb(Math.Min(255,colors[i].R+10),Math.Min(255,colors[i].G+12),colors[i].B):colors[i]});}all.AddRange(v.Select(project));labels.Add(Tuple.Create(new P(x+w/2,y+d/2,z+t+5),J.Text(b,"index")));}double minx=all.Min(v=>v[0]),maxx=all.Max(v=>v[0]),miny=all.Min(v=>v[1]),maxy=all.Max(v=>v[1]);double scale=Math.Min((Width-100)/Math.Max(1,maxx-minx),(Height-100)/Math.Max(1,maxy-miny))*Zoom;Func<P,PointF> screen=v=>{double[] q=project(v);return new PointF((float)(Width/2+(q[0]-(minx+maxx)/2)*scale),(float)(Height/2+(q[1]-(miny+maxy)/2)*scale));};using(var pen=new Pen(Color.FromArgb(92,71,47),.8f))foreach(Face f in faces.OrderBy(f=>f.Depth)){PointF[] points=f.Points.Select(screen).ToArray();using(var brush=new SolidBrush(f.Color))g.FillPolygon(brush,points);g.DrawPolygon(pen,points);}if(boxes.Count<=45)using(var font=new Font("���� ����",8))foreach(var l in labels){PointF at=screen(l.Item1);g.DrawString(l.Item2,font,Brushes.Black,at);}using(var font=new Font("���� ����",9))g.DrawString("3D ġ�� ���� �� �巡�� ȸ�� / �� Ȯ�� �� ��ȣ=��� ����\n����� �ٴ��� ������ �����̸� ���� �������� ���� �ʽ��ϴ�.",font,Brushes.DarkGreen,12,12);}}
