bool Calculate(bool alert){if(!ready)return false;try{result=bridge.Call("stairs",ReadInput());view.Model=result;view.Invalidate();string clearance=result["minClearance"]==null?(opening.Checked?"������ �� / �ٸ� ��ֹ� �̰˻�":"��Ȯ��"):J.Num(result,"minClearance").ToString("N1")+"mm";summary.Text="�ܳ��� "+J.Num(result,"rise").ToString("N3")+"mm   �� ����� "+J.Num(result,"going")+"mm   �� ���� ��� "+J.Num(result,"pitch").ToString("N2")+"��\r\n���� "+J.Num(result,"treadCount")+"�� / ����� "+J.Num(result,"landingCount")+"�� �� ���� ���� "+J.Num(result,"footprintX")+" �� "+J.Num(result,"footprintY")+"mm\r\n��� ���� "+clearance+" �� ���������ԡ����� ���� �ƴ�";var checks=J.Rows(result,"issues");summary.ForeColor=checks.Any(x=>J.Text(x,"level")=="error")?Color.Firebrick:Color.FromArgb(92,73,24);cuts.Columns.Clear();foreach(string h in new[]{"����","����","X mm","Y mm","��� Z mm","��� X mm","��� Y mm","�β� mm"})cuts.Columns.Add(h,h);foreach(D box in J.Rows(result,"boxes"))cuts.Rows.Add(J.Text(box,"label"),J.Num(box,"index"),J.Num(box,"x"),J.Num(box,"y"),J.Num(box,"top"),J.Num(box,"width"),J.Num(box,"depth"),J.Num(box,"thickness"));levels.Columns.Clear();foreach(string h in new[]{"�ܳ��� ��ȣ","���� ���� ���� mm","�ش� �ܳ��� mm","����"})levels.Columns.Add(h,h);foreach(D level in J.Rows(result,"levels"))levels.Rows.Add(J.Num(level,"riser"),J.Num(level,"level"),J.Num(level,"rise"),J.Text(level,"kind"));issues.Text=String.Join("\r\n",checks.Select(x=>"["+J.Text(x,"level")+"] "+J.Text(x,"text")))+"\r\n\r\n�Է� �⺻���� ���� ���䰪�̸� ���� ���� ������ �ƴմϴ�. ���� ���� ���� ���� ���� ��ȿ���� �ٸ� �� �ֽ��ϴ�.\r\n�ܼ� N�� ��ü ��� Ƚ���Դϴ�. ������ ������ N-1��, ����� 1���� ������ �Ϲ� ������ N-2���Դϴ�.\r\n��ħ ������ ���� ��� ���̿� �����մϴ�. ���� Ȩ����ħ����Ŀ������������ ���ߡ����� ������ ������� �ʽ��ϴ�.\r\n��� ������ ���簢�� ������ ���� ����/����� ��ü ���������� ���������� �˻��մϴ�. õ�� ������Ʈ����� ���� ���� �������� �ʽ��ϴ�.\r\n���� ������ �Ϻ� �ϼ� �ٴ� 0�� �������� �ϸ�, ���ǥ�� ��ǥ�� ��ü ���� ���� �ּ� X/Y��