void SaveDesign(){if(!Calculate(true))return;if(title.Text.Trim()==""){MessageBox.Show("������� �Է��ϼ���.");return;}D d=J.Clone(original);d["name"]=title.Text.Trim();d["project"]=((Choice)project.SelectedItem).Id;d["inputs"]=ReadInput();d["updatedAt"]=DateTime.Now.ToString("o");d["reviewStatus"]=J.Bool(result,"geometryChecksPassed")?"ġ�� ���� / ���� ��":"ġ�� ���� ���� �ʿ�";if(save(d)){MessageBox.Show("���踦 �����߽��ϴ�. �ð� ���� �ڷ�� �ƴմϴ�.");}}
