void Export(){try{bridge.Call("backup");}catch(Exception ex){MessageBox.Show(ex.Message);return;}if(!Calculate(true))return;using(var f=new SaveFileDialog{Filter="3D OBJ (mm)|*.obj|���� JSON|*.json|���ǥ CSV|*.csv",FileName="������-��ܼ���"})if(f.ShowDialog()==DialogResult.OK){string ext=Path.GetExtension(f.FileName).ToLower();if(ext==".json")File.WriteAllText(f.FileName,J.S.Serialize(J.Row("name",title.Text,"result",result)),System.Text.Encoding.UTF8);else if(ext==".obj")File.WriteAllText(f.FileName,ToObj(result),System.Text.Encoding.UTF8);else{var rows=new List<string>{"����,����,X_mm,Y_mm,���Z_mm,���X_mm,���Y_mm,�β�_mm"};foreach(D box in J.Rows(result,"boxes"))rows.Add("\""+J.Text(box,"label").Replace("\"","\"\"")+"\","+String.Join(",",new[]{"index","x","y","top","width","depth","thickness"}.Select(k=>J.Num(box,k).ToString(System.Globalization.CultureInfo.InvariantCulture))));rows.Add("\"����� / �������ð� ���� �ƴ�\"");File.WriteAllLines(f.FileName,rows,new System.Text.UTF8Encoding(true));}}}
public static string ToObj(D model){var s=new System.Text.StringBuilder("# OreumMok parametric stair model\n# Units: millimeters. Review only; not structural approval.\n");int start=1;foreach(D box in J.Rows(model,"boxes")){double x=(double)J.Num(box,"x"),y=(double)J.Num(box,"y"),z=(double)J.Num(box,"z"),w=(double)J.Num(box,"width"),d=(double)J.Num(box,"depth"),t=(double)J.Num(box,"thickness");double[][] v={new[]{x,y,z},new[]{x+w,y,z},new[]{x+w,y+d,z},new[]{x,y+d,z},new[]{x,y,z+t},new[]{x+w,y,z+t},new[]{x+w,y+d,z+t},new[]{x,y+d,z+t}};s.AppendLine("o part_"+start);foreach(var point in v)s.AppendLine("v "+String.Join(" ",point.Select(n=>n.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture))));foreach(int[] face in new[]{new[]{0,3,2,1},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}})s.AppendLine("f "+String.Join(" ",face.Select(n=>(n+start).ToString())));start+=8;}return s.ToString();}
